51	     * Derives the owner's numeric membership level. Starts at 1; add 1 when an email
52	     * address is on file; add 1 when the owner is the first with their name
53	     * ({@code namesakeCount} is 0). These at-creation factors are capped at 3. Level 4 is
54	     * reserved for tenure: add 1 once the owner's tenure exceeds 365 days. Because a newly
55	     * created owner has zero tenure, a new owner never exceeds level 3.
56	     */
57	    protected Integer membershipLevel(Owner owner) {
58	        int level = 1;
59	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
60	            level++;
61	        }
62	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
63	            level++;
64	        }
65	        level = Math.min(level, 3);
66	        if (tenureDays(owner) > 365) {
67	            level++;
68	        }
69	        return level;
70	    }
