72	    /**
73	     * The owner's tenure in whole days, measured from their {@code registrationDate} to
74	     * the current date. Returns 0 when no registrationDate is on file (e.g. a brand-new
75	     * owner before one is assigned), so such an owner has zero tenure.
76	     */
77	    private long tenureDays(Owner owner) {
78	        LocalDate registrationDate = owner.getRegistrationDate();
79	        if (registrationDate == null) {
80	            return 0;
81	        }
82	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
83	    }
84	
85	    /**
86	     * Computes a single Luhn check digit (0-9) over the digits contained in the owner's
87	     * {@code customerCode}. Non-digit characters (separators) are ignored. Returns
88	     * {@code null} when no customer code has been assigned.
89	     */
90	    protected Integer checkDigit(Owner owner) {
91	        String code = owner.getCustomerCode();
92	        if (code == null) {
93	            return null;
94	        }
95	        int sum = 0;
96	        boolean dbl = true;
97	        for (int i = code.length() - 1; i >= 0; i--) {
98	            char c = code.charAt(i);
99	            if (c < '0' || c > '9') {
100	                continue;
101	            }
102	            int d = c - '0';
103	            if (dbl) {
104	                d *= 2;
105	                if (d > 9) {
106	                    d -= 9;
107	                }
108	            }
109	            sum += d;
110	            dbl = !dbl;
111	        }
112	        return (10 - (sum % 10)) % 10;
113	    }
