117	     * {@code <REGION>-<HASH8>} customer code — the region-and-hash identity is now the single
118	     * source of the owner's region. Falls back to the postcode/city lookup for an owner that has
119	     * no customer code yet (e.g. seed data created outside the create pipeline).
120	     */
121	    protected String locality(Owner owner) {
122	        String code = owner.getCustomerCode();
123	        if (code != null) {
124	            int dash = code.indexOf('-');
125	            return dash >= 0 ? code.substring(0, dash) : code;
126	        }
127	        return LocalityLookup.regionFor(owner.getCity(), owner.getPostcode());
128	    }
