138	    /**
139	     * Derives the owner's age band from their birthDate as of their registrationDate:
140	     * 'MINOR' when under 18, 'ADULT' when 18-64, 'SENIOR' when 65 or over. Returns
141	     * {@code null} when no birthDate is on file (the field is then absent from the
142	     * response). The reference date is the registrationDate, falling back to the current
143	     * date only for legacy owners created without one.
144	     */
145	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
146	        LocalDate birthDate = owner.getBirthDate();
147	        if (birthDate == null) {
148	            return null;
149	        }
150	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
151	        int age = Period.between(birthDate, asOf).getYears();
152	        if (age < 18) {
153	            return OwnerDto.AgeBandEnum.MINOR;
154	        }
155	        if (age < 65) {
156	            return OwnerDto.AgeBandEnum.ADULT;
157	        }
158	        return OwnerDto.AgeBandEnum.SENIOR;
159	    }
