package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Temporary probe: a 3-member household (same lastName+postcode) should add 2 points. */
class HouseholdPointsProbe extends AcceptanceBase {

	@Test
	void householdOfThreeAddsTwoPoints() throws Exception {
		String last = uniqueLastName();
		int last3 = 0;
		for (int i = 0; i < 3; i++) {
			ObjectNode o = withPostcode(ownerNode());
			o.put("lastName", last);
			o.put("email", uniqueEmail());
			o.put("sharesHousehold", true);
			last3 = createOwnerOk(o);
		}
		// 3rd member: email(+2) + namesake0(+1) + household3(+2) = 5 points -> level 3
		getOwner(last3).andExpect(jsonPath("$.membershipPoints").value(5))
				.andExpect(jsonPath("$.membershipLevel").value(3));
	}
}
EOF
./mvnw -o test -Dtest=HouseholdPointsProbe >/tmp/probe.log 2>&1; echo "EXIT=$?"; grep -E "Tests run:|BUILD" /tmp/probe.log | tail -4

