package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

class HouseholdPointsProbe extends AcceptanceBase {

	@Test
	void householdOfThreeAddsTwoPoints() throws Exception {
		String last = uniqueLastName();
		int third = 0;
		for (int i = 0; i < 3; i++) {
			ObjectNode o = withPostcode(ownerNode());
			o.put("firstName", uniqueFirstName()); // unique -> namesakeCount stays 0
			o.put("lastName", last);               // shared -> same household
			o.put("email", uniqueEmail());
			o.put("sharesHousehold", true);
			third = createOwnerOk(o);
		}
		// email(+2) + namesake0(+1) + household-of-3(+2) = 5 -> level 3
		getOwner(third).andExpect(jsonPath("$.membershipPoints").value(5))
				.andExpect(jsonPath("$.membershipLevel").value(3));
	}
}
EOF
